void Solver::bump_var(int var, double coeff) {
    // Compute the increment for this variable.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // If any activity becomes too large, rescale all activities and the increment.
    const double RESCALE_LIMIT = 1e150;
    if (activity[var] > RESCALE_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Update the VSIDS heap only when the variable is already present.
    // This avoids unnecessary heap operations for variables that are not yet in the heap.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
